describe('tool validator interoperability', () => {
  it('rejects a wrong typed field without exposing its value specs/hal-engine-tool-input-validation/spec.md#2', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    const execute = async () => {
      calls++;
      return 'ok';
    };
    registry.register(
      {
        name: 'forecast',
        description: 'Forecast',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      execute
    );
    const response = await registry.execute('forecast', {location: 123456});
    expect({
      result: response.result,
      leaked: response.result.includes('123456'),
      calls,
    }).toEqual({
      result: expect.stringMatching(/location.*string/),
      leaked: false,
      calls: 0,
    });
  });
});
